#nullable enable
#if UNITY_EDITOR
using UnityEngine;

namespace Playloop.Editor
{
    /// <summary>
    /// Embedded Playloop wordmark lockup (the playloop.gg mark: infinity-as-"oo"
    /// + ".gg", white text + gradient glyph, transparent bg). Rendered from the
    /// site's canonical public/playloop-wordmark.svg (441x96 PNG, base64) so the
    /// editor settings window header matches the marketing site exactly. Embedded
    /// as bytes (like Runtime/Feedback/PlayloopBrandingLogo) so it loads with no
    /// Resources folder or import settings. Regenerate if the wordmark changes.
    /// </summary>
    internal static class PlayloopBrandingWordmark
    {
        private const string PngBase64 =
            "";

        private static Texture2D? _cached;

        /// <summary>
        /// Decode the embedded PNG into a Texture2D, cached after first use.
        /// Returns null if decoding fails (caller falls back to a text label).
        /// </summary>
        public static Texture2D? Texture()
        {
            if (_cached != null) return _cached;
            var bytes = System.Convert.FromBase64String(PngBase64);
            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, mipChain: false)
            {
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
            };
            if (!tex.LoadImage(bytes)) return null;
            _cached = tex;
            return _cached;
        }
    }
}
#endif
